def three_sum_closest(nums, target):
    nums.sort()
    n = len(nums)
    best_sum = nums[0] + nums[1] + nums[2]
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if abs(current_sum - target) < abs(best_sum - target):
                best_sum = current_sum                                # a closer sum has been found
            if current_sum == target:
                return current_sum                                      # cannot possibly get any closer than exact
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return best_sum


